// 模拟向量数据库检索接口
app.post('/api/knowledge/query', (req, res) => {
  const { query, top_k } = req.body;
  if (!query) return res.status(400).json({ error: "Missing parameter: query" });

  console.log(`[RAG Database] Querying for: "${query}" (top_${top_k || 5})`);

  const mockRags = [
    {
      document_name: "昆仑增长冷启动运营手册.pdf",
      content: "冷启动起号的7步工作流：1.确定细分人群画像；2.利用冲突模型设计选题；3.去AI腔调文案撰写；4.首封关注流设置；5.微信openclaw私域沉淀；6.BANT转化跟进；7.多维表格交付履约。",
      score: 0.89
    },
    {
      document_name: "AI销冠标准答疑话术.docx",
      content: "应对‘价格贵’异议：同理心拥抱（‘我理解您的顾虑，很多同行起步时也是这么看’） -> ROI成本拆解（‘但如果这套Agent能帮你把日均转化从2%提升到5%，多赚的利润在一周内就能收回成本’） -> 制造紧迫感。",
      score: 0.82
    }
  ];

  const hits = mockRags.filter(rag => 
    query.includes("冷启动") || query.includes("话术") || query.includes("价格") || 
    rag.content.toLowerCase().includes(query.toLowerCase())
  );

  res.json({ success: true, hits: hits.length > 0 ? hits : [
    {
      document_name: "通用常识汇编.txt",
      content: `在知识库中未查到与“${query}”精确对齐的规章，当前返回通用知识归档说明。`,
      score: 0.50
    }
  ] });
});

